def identify_material(reflection, conductivity, density):
  """Identifies material as glass or metal."""
  if reflection < 0.3 and conductivity < 1 and density < 5:
    return "Glass"
  elif reflection > 0.7 and conductivity > 5 and density > 3:
    return "Metal"
  else:
    return "Unknown"
